import java.util.*;

public class Cutting {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String firstLine = sc.nextLine();
        String[] parts = firstLine.split(" ");
        int n = Integer.parseInt(parts[0]);
        int coinsAvailable = Integer.parseInt(parts[1]);
        String[] vals = sc.nextLine().split(" ");
        int oddCount = 0, evenCount = 0, result = 0;
        List<Integer> diffList = new ArrayList<>();
        for (int i = 0; i < n - 1; i++) {
            int val = Integer.parseInt(vals[i]);
            if (val % 2 == 0) {
                evenCount++;
            } else {
                oddCount++;
            }
            if (oddCount == evenCount) {
                int nextVal = Integer.parseInt(vals[i + 1]);
                int diff = Math.abs(nextVal - val);
                diffList.add(diff);
            }
        }
        Collections.sort(diffList);
        for (int diff : diffList) {
            if (diff <= coinsAvailable) {
                coinsAvailable -= diff;
                result++;
            } else {
                break;
            }
        }
        System.out.println(result);
    }
}
