#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdlib>

int main() {
    int n, coinsAvailable;
    std::string firstLine;
    std::getline(std::cin, firstLine);
    std::istringstream iss(firstLine);
    iss >> n >> coinsAvailable;

    std::string secondLine;
    std::getline(std::cin, secondLine);
    std::istringstream iss2(secondLine);
    std::vector<int> vals(n);
    for (int i = 0; i < n; ++i) {
        iss2 >> vals[i];
    }

    int oddCount = 0, evenCount = 0, result = 0;
    std::vector<int> diffList;

    for (int i = 0; i < n - 1; ++i) {
        int val = vals[i];
        if (val % 2 == 0) {
            ++evenCount;
        } else {
            ++oddCount;
        }
        if (oddCount == evenCount) {
            int nextVal = vals[i + 1];
            int diff = std::abs(nextVal - val);
            diffList.push_back(diff);
        }
    }

    std::sort(diffList.begin(), diffList.end());

    for (int diff : diffList) {
        if (diff <= coinsAvailable) {
            coinsAvailable -= diff;
            ++result;
        } else {
            break;
        }
    }

    std::cout << result << std::endl;
    return 0;
}
